def add(a, b):
    return a + b

def test_add_two_positive():
    assert add(2, 3) == 5

def test_add_negative():
    assert add(-1, 1) == 0

tests = [test_add_two_positive, test_add_negative]
passed = 0
for t in tests:
    try:
        t()
        passed += 1
        print(f"{t.__name__}: PASSED")
    except AssertionError:
        print(f"{t.__name__}: FAILED")
print(f"{passed}/{len(tests)} passed")
